<script setup>
import { ref, shallowRef, onBeforeUnmount } from 'vue'
import bank from '@/data/scene850.json'
import { createSession,nextQuestion,submitAnswer,placementResult } from '@/domain/placement.mjs'
const confidenceLabel = () => '初步；待学习验证'
import { useLearnerStore } from '@/stores/learner'
import { speakText,stopSpeaking,feedbackSound } from '@/services/audio'
const learner=useLearnerStore(),started=ref(false),session=shallowRef(null),question=ref(null),result=ref(null),busy=ref(false),chosen=ref(''),feedback=ref(''),status=ref(''),count=ref(0),animation=ref('');let timer
function begin(){session.value=createSession(({new:80,little:200,basic:400,comfortable:650})[learner.profile.selfLevel]||100);started.value=true;result.value=null;count.value=0;next()}
function next(){question.value=nextQuestion(session.value,bank.rows);if(!question.value)return finish();chosen.value='';feedback.value='';busy.value=false;animation.value='';stopSpeaking()}
function choose(optionId){if(busy.value)return;const current=question.value,answer=submitAnswer(session.value,current.id,optionId);if(!answer)return;busy.value=true;chosen.value=optionId;count.value=session.value.responses.length;animation.value=answer.outcome==='correct'?'correct':'wrong';feedback.value=answer.outcome==='correct'?`${current.item.word}：识读正确`:answer.outcome==='unknown'?`${current.item.word}：已记录为不会，后续会给你支持`:`${current.item.word}：这里是“${current.item.meaning}”，已记录为需巩固`;feedbackSound(answer.outcome==='correct');timer=setTimeout(()=>session.value.done?finish():next(),750)}
function finish(){result.value=placementResult(session.value);learner.applyPlacement(result.value);stopSpeaking()}
onBeforeUnmount(()=>{clearTimeout(timer);stopSpeaking()})
</script>
<template><section class="placement"><header><span class="section-label">850词场景图谱</span><h1>{{result?'先从舒服的地方开始。':'认识就选，不会就说。'}}</h1><p class="muted">评估这份词表中的识读情况。后续用文章、听力和表达继续确认。</p></header><div v-if="!started" class="panel test-intro"><img src="/assets/alex-mentor.png" alt="Alex"/><div><h2>我会一点点找到适合你的内容。</h2><p class="muted">每个词只出现一次。几道答对不会直接变成几百个“已掌握词”。</p><div class="actions"><button class="btn btn-primary" @click="begin">开始基础测试</button><RouterLink class="btn btn-ghost" to="/onboarding">调整我的信息</RouterLink></div></div></div>
<div v-else-if="!result&&question" class="test-body"><div class="quiz-meta"><span>第 {{count+1}} 题 / 共30题</span><span>覆盖10个学习模块</span></div><div class="progress-bar"><i :style="{width:`${count/30*100}%`}"/></div><div class="word-stage" :class="animation"><span class="section-label">{{question.item.source_category}}</span><strong class="reading-font">{{question.item.word}}</strong><button class="btn btn-secondary" @click="speakText(question.item.word,{onError:e=>status=e})">听这个词</button></div><div class="options"><button v-for="opt in question.options" :key="opt.id" class="option" :class="{chosen:chosen===opt.id}" :disabled="busy" @click="choose(opt.id)">{{opt.text}}</button><button class="option unknown" :disabled="busy" @click="choose('unknown')">我不会 / 没见过</button></div><p class="feedback" aria-live="polite">{{feedback||'不确定时选“我不会”，会让第一篇文章更合适。'}}</p><p v-if="status" class="notice" role="status">{{status}}</p></div>
<div v-else-if="result" class="result"><div class="estimate"><strong>{{result.summary.median}}</strong><span>/ 850 条词形，初步估计</span></div><p class="muted">估计区间 {{result.summary.low}}—{{result.summary.high}}，可信度{{confidenceLabel(result.summary)}}。<br>这是识读定位，还需要确认听懂和会用。</p><div class="result-grid"><div><strong>{{result.breakdown.observed.correct}}</strong>实际答对</div><div><strong>{{result.breakdown.observed.wrong}}</strong>实际答错</div><div><strong>{{result.breakdown.observed.unknown}}</strong>明确不会</div><div><strong>{{result.breakdown.untested}}</strong>尚未测试</div></div><p class="notice">估计认识 {{result.breakdown.knownPercent}}%，其余约 {{result.breakdown.unknownPercent}}% 可能需要帮助。未测词仍然是“未测”，不会自动标成已掌握。</p><RouterLink class="btn btn-primary" to="/learn">看看适合我的第一篇</RouterLink></div></section></template>
<style scoped>.placement{max-width:700px;margin:25px auto}.placement h1{font-size:36px;font-weight:550;margin:13px 0}.placement header p{font-size:14px}.test-intro{display:flex;gap:25px;padding:32px;margin-top:32px;align-items:center}.test-intro img{width:90px}.test-intro h2{font-size:21px}.test-intro p{font-size:13px}.test-body{margin-top:32px}.quiz-meta{display:flex;justify-content:space-between;font-size:12px;color:var(--ink-muted)}.progress-bar{height:4px;background:#e5eee8;border-radius:10px;margin:15px 0 24px;overflow:hidden}.progress-bar i{display:block;height:100%;background:var(--brand);transition:width .3s}.word-stage{text-align:center;border-radius:24px;background:linear-gradient(120deg,#f1f8f4,#f4f8fe);padding:35px;border:1px solid var(--line);transition:background .2s}.word-stage strong{display:block;font-size:64px;font-weight:400;margin:17px 0 24px}.word-stage.correct{background:#e1f3e8;animation:confirm .3s}.word-stage.wrong{background:#f9f0ee}.options{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-top:22px}.option{border:1px solid var(--line);background:white;border-radius:13px;padding:16px 20px;text-align:left;min-height:62px}.option:hover,.option.chosen{border-color:var(--brand);background:var(--brand-soft)}.unknown{grid-column:1/-1;text-align:center;color:var(--ink-muted);background:#f5f8f6}.feedback{min-height:40px;font-size:13px;color:var(--ink-muted)}.result{text-align:center;margin-top:35px}.estimate{display:flex;align-items:baseline;justify-content:center;gap:12px}.estimate strong{font-size:80px;font-weight:400}.estimate span{font-size:12px;color:var(--ink-muted)}.result-grid{display:grid;grid-template-columns:repeat(4,1fr);border:1px solid var(--line);border-radius:17px;margin:25px 0}.result-grid div{padding:20px;font-size:12px;color:var(--ink-muted)}.result-grid strong{display:block;color:var(--ink);font-size:27px;font-weight:500}.result .notice{text-align:left}.result .btn{margin-top:20px}@keyframes confirm{50%{transform:scale(1.015)}}@media(max-width:550px){.test-intro{padding:22px;display:block}.test-intro img{width:65px}.options{grid-template-columns:1fr}.result-grid{grid-template-columns:1fr 1fr}.placement h1{font-size:29px}.estimate strong{font-size:62px}}</style>
